import sys
input = sys.stdin.read
data = input().split()

n, x, y = map(int, data[:3])
edges = [tuple(map(int, data[i:i+2])) for i in range(3, len(data), 2)]

adj_list = {}
for a, b in edges:
    if a not in adj_list:
        adj_list[a] = []
    if b not in adj_list:
        adj_list[b] = []
    adj_list[a].append(b)
    adj_list[b].append(a)

def dfs(node, parent, target, visited):
    if node == target:
        return 1
    for neighbor in adj_list[node]:
        if neighbor != parent:
            visited += dfs(neighbor, node, target, visited)
    return visited

result = n * (n - 1) - dfs(x, -1, y, 0) * dfs(y, -1, x, 0)
print(result)

